import{z}from'zod';import{createServerSupabaseClient}from'@/src/lib/supabase';import{requireOrganizationContext}from'@/app/actions/_shared';import{createHmac,createHash}from'crypto';export const runtime='nodejs';const s=z.object({url:z.string().url(),eventType:z.string().min(2),payload:z.record(z.string(),z.unknown()),secret:z.string().min(16)});export async function POST(r:Request){const a=await requireOrganizationContext('admin');if(!a.success)return Response.json(a,{status:401});try{const p=s.parse(await r.json());const body=JSON.stringify({organizationId:a.data.organizationId,eventType:p.eventType,payload:p.payload});const res=await fetch(p.url,{method:'POST',headers:{'content-type':'application/json','x-fluxentiq-signature':createHmac('sha256',p.secret).update(body).digest('hex')},body});const db=await createServerSupabaseClient();await db.from('external_webhook_logs').insert({organization_id:a.data.organizationId,direction:'outbound',event_type:p.eventType,endpoint:p.url,status_code:res.status,payload_hash:createHash('sha256').update(body).digest('hex')});return Response.json({success:res.ok,data:{status:res.status},error:res.ok?undefined:'External endpoint rejected request.'},{status:res.ok?202:502})}catch(e){return Response.json({success:false,error:e instanceof z.ZodError?e.issues.map(i=>i.message).join(' '):'Invalid outbound trigger.'},{status:400})}}